import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_request_signature(payload, signature):
    """Verify webhook signature from upstream service"""
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def sanitize_sort_field(field):
    """Allow only known sort columns"""
    allowed = {'username', 'created_at', 'email', 'status', 'last_login'}
    if field in allowed:
        return field
    return 'created_at'

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users with filtering capabilities"""
    query_term = request.args.get('q', '')
    department = request.args.get('dept', '')
    sort_by = sanitize_sort_field(request.args.get('sort', 'created_at'))
    page = request.args.get('page', '1')

    # Validate page is numeric
    try:
        page_num = int(page)
        if page_num < 1:
            page_num = 1
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 25

    db = get_db()

    # Build query with department filter
    if department:
        # Department comes from a controlled dropdown in the UI
        sql = f"SELECT id, username, email, department, status FROM users WHERE department = '{department}' AND (username LIKE ? OR email LIKE ?) ORDER BY {sort_by} LIMIT 25 OFFSET {offset}"
        like_term = f'%{query_term}%'
        cursor = db.execute(sql, (like_term, like_term))
    else:
        sql = f"SELECT id, username, email, department, status FROM users WHERE (username LIKE ? OR email LIKE ?) ORDER BY {sort_by} LIMIT 25 OFFSET {offset}"
        like_term = f'%{query_term}%'
        cursor = db.execute(sql, (like_term, like_term))

    results = [dict(row) for row in cursor.fetchall()]
    return jsonify({'users': results, 'page': page_num})

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - parameterized query"""
    db = get_db()
    cursor = db.execute('SELECT id, username, email, department, status, created_at FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users/<int:user_id>/notes', methods=['POST'])
def add_note(user_id):
    """Add admin note to user - requires signature verification"""
    sig = request.headers.get('X-Webhook-Signature', '')
    body = request.get_data(as_text=True)

    if not verify_request_signature(body, sig):
        return jsonify({'error': 'invalid signature'}), 403

    data = request.get_json()
    note = data.get('note', '')
    db = get_db()
    db.execute('INSERT INTO user_notes (user_id, note, created_at) VALUES (?, ?, datetime("now"))', (user_id, note))
    db.commit()
    return jsonify({'status': 'ok'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
